input.command:
cd /app/work; python3 -c "
import json
pats=json.load(open('patients.json'))['resources']
living={p['id'] for p in pats if not p.get('deceasedDateTime')}
dead={p['id']:p['deceasedDateTime'] for p in pats if p.get('deceasedDateTime')}
print('living',len(living),'dead',len(dead))
e=json.load(open('ecgs.json'))['ecgs']
pe={}
for x in e: pe.setdefault(x['patient'],[]).append(x)
print('living with ecg', len([k for k in pe if k in living]))
print('living without ecg', len([k for k in living if k not in pe]))
print('dead with ecg', [ (k,dead[k]) for k in pe if k in dead])
"

