import json
from collections import Counter,defaultdict
enc={}
for l in open('Encounter.ndjson'):
    e=json.loads(l); enc[e['id']]=e
meds={}
for l in open('Medication.ndjson'):
    m=json.loads(l); code=m.get('code',{})
    meds[m['id']]=code.get('text') or (code.get('coding') or [{}])[0].get('display') or (code.get('coding') or [{}])[0].get('code')
rs=[json.loads(l) for l in open('MedicationRequest.ndjson')]
def name(r):
    if 'medicationReference' in r: return meds.get(r['medicationReference']['reference'].split('/')[-1],'?')
    c=r.get('medicationCodeableConcept',{})
    return c.get('text') or (c.get('coding') or [{}])[0].get('display') or (c.get('coding') or [{}])[0].get('code')
amb=[r for r in rs if r.get('encounter') and enc.get(r['encounter']['reference'].split('/')[-1],{}).get('class',{}).get('code')=='AMB']
print(len(amb))
print(Counter(name(r) for r in amb).most_common(40))
noenc=[r for r in rs if not r.get('encounter')]
print('noenc',len(noenc))
EOF

