import numpy as np, wfdb, neurokit2 as nk
def delin(e,lead=1):
    rec=wfdb.rdrecord('ecg/'+e); fs=rec.fs
    s=np.nan_to_num(rec.p_signal[:,lead])
    c=nk.ecg_clean(s,sampling_rate=fs)
    _,info=nk.ecg_peaks(c,sampling_rate=fs,correct_artifacts=True)
    r=info['ECG_R_Peaks']
    for m in ['dwt','peak']:
        try:
            _,w=nk.ecg_delineate(c,rpeaks=r,sampling_rate=fs,method=m)
        except Exception as ex:
            print(e,m,'fail',ex); continue
        def med(k):
            v=np.array(w.get(k,[]),dtype=float); v=v[~np.isnan(v)]
            return v
        Qon=med('ECG_R_Onsets'); Roff=med('ECG_R_Offsets'); Toff=med('ECG_T_Offsets'); Pon=med('ECG_P_Onsets'); Poff=med('ECG_P_Offsets')
        rr=np.median(np.diff(r))/fs
        def pairdiff(a,b):
            # match nearest
            out=[]
            for x in a:
                cand=b[(b>x)&(b<x+0.6*fs)]
                if len(cand): out.append((cand[0]-x)/fs*1000)
            return np.median(out) if out else None
        qrs=pairdiff(Qon,Roff); qt=pairdiff(Qon,Toff); pr=pairdiff(Pon,Qon)
        print(e,m,'rate',round(60/rr,1),'QRS',qrs,'QT',qt,'QTc',round(qt/np.sqrt(rr),1) if qt else None,'PR',pr, 'nP',len(Pon))
for e in ['103088543','107914094','104882441','102172660']:
    delin(e)
