import json, numpy as np
from collections import defaultdict
from ecg3 import analyze, rhythm_features
pats=json.load(open('patients.json'))['resources']
living={p['id'] for p in pats if not p.get('deceasedDateTime')}
info={p['id']:p for p in pats}
e=json.load(open('ecgs.json'))['ecgs']
byp=defaultdict(list)
for x in e:
    if x['patient'] in living: byp[x['patient']].append(x)
