    for i in m.get('identifier',[]):
        if i['system'].endswith('medication-name'): nm=i['value']
    meds[m['id']]=nm
enc={}
for l in open('Encounter.ndjson'):
    e=json.loads(l); enc[e['id']]=e
rs=[json.loads(l) for l in open('MedicationRequest.ndjson')]
def name(r):
    if 'medicationReference' in r: return meds.get(r['medicationReference']['reference'].split('/')[-1],'?')
    c=r.get('medicationCodeableConcept',{})
    return c.get('text') or (c.get('coding') or [{}])[0].get('display') or (c.get('coding') or [{}])[0].get('code')
WATCH=['citalopram','escitalopram','haloperidol','methadone','amiodarone','sotalol','dofetilide']
byp=defaultdict(list)
for r in rs:
    nm=(name(r) or '').lower()
    if not any(w in nm for w in WATCH): continue
    byp[r['subject']['reference'].split('/')[-1]].append(r)
pats={p['id']:p for p in json.load(open('patients.json'))['resources']}
for p,l in sorted(byp.items()):
    l.sort(key=lambda r:r['authoredOn'])
    print('###',p,'dead' if pats[p].get('deceasedDateTime') else 'LIVE')
    prev_end=None; prev_name=None
    for r in l:
        nm=name(r); vp=r.get('dispenseRequest',{}).get('validityPeriod',{})
        s=vp.get('start',r['authoredOn']); e=vp.get('end')
        ph=[i['value'] for i in r.get('identifier',[]) if i['system'].endswith('phid')]
        syn=bool(ph) and int(ph[0])>=100000000
        E=enc.get((r.get('encounter') or {}).get('reference','').split('/')[-1],{})
        cls=E.get('class',{}).get('code'); svc=(E.get('serviceType') or {}).get('coding',[{}])[0].get('code')
        print(f"   {r['authoredOn'][:16]} {nm:22s} syn={syn} {s[:10]}->{(e or '')[:10]} {r['status']:9s} enc={cls}/{svc} {r['id']}")
EOF

