import sys; sys.path.insert(0,'lib')
import json, numpy as np
from collections import defaultdict
from ecg3 import analyze
pats=json.load(open('patients.json'))['resources']
living={p['id'] for p in pats if not p.get('deceasedDateTime')}
e=json.load(open('ecgs.json'))['ecgs']
byp=defaultdict(list)
for x in e:
    if x['patient'] in living: byp[x['patient']].append(x)
out={}
for p,l in sorted(byp.items()):
    l.sort(key=lambda x:x['time'])
    rec={'patient':p,'latest':l[-1]['ecg'],'latest_time':l[-1]['time'],'prior':(l[-2]['ecg'] if len(l)>1 else None)}
    for k,ecgid in [('L',rec['latest']),('P',rec['prior'])]:
        if not ecgid: continue
        try:
            o=analyze(ecgid)
        except Exception as err:
            rec[k]={'err':str(err)}; continue
        rec[k]={'ecg':ecgid,'rate':round(o['rate']),'pr':o['pr_ms'],'qrs':round(o['qrs_ms']),'qt':round(o.get('qt_ms') or 0),'qtc':round(o.get('qtc_ms') or 0),'axis':round(o['axis_area']),'rr_cv':round(o['rr_cv'],2)}
    out[p]=rec
json.dump(out,open('final_base.json','w'),indent=1)
for p,r in out.items():
    print(p[:8], r['latest_time'][:10], 'L',r.get('L'), '| P',r.get('P'))
EOF

