input.command:
cd /app/work; python3 - <<'EOF'
import json,re
blks=open('notes.txt').read().split('\n### ')
liv={p['id'] for p in json.load(open('patients.json'))['resources'] if not p.get('deceasedDateTime')}
last={}
for b in blks:
    m=re.match(r'PT (\S+) \| NOTE (\S+) \| (\S+)',b)
    if not m: continue
    p,nid,dt=m.groups()
    mm=re.search(r'Current medications: (.+)',b)
    if mm and p in liv:
        if p not in last or dt>last[p][0]: last[p]=(dt,mm.group(1),nid)
AC=['warfarin','apixaban','rivaroxaban','dabigatran','edoxaban','enoxaparin','heparin']
QT=['citalopram','escitalopram','haloperidol','methadone','amiodarone','sotalol','dofetilide']
for p,(dt,meds,nid) in sorted(last.items(),key=lambda kv:kv[1][0]):
    ml=meds.lower()
    a=[k for k in AC if k in ml]; q=[k for k in QT if k in ml]
    if a or q: print(dt[:10],p[:8],'AC:',a,'QT:',q)
EOF

